L70: /** @param {string} dir */
L71: export function readMetrics(dir) {
L72:   const data = readJson(path.join(dir, CACHE_FILE));
L73:   return data && typeof data === "object" ? data : null;
L74: }
L75: 
L76: /**
L77:  * The one freshness rule for every cached entry (a metrics source or a
L78:  * per-model detail): fetched less than TTL_MS ago. At exactly TTL_MS it has
L79:  * expired.
L80:  *
L81:  * @param {{fetchedAt?: unknown} | null | undefined} entry
L82:  * @param {number} now
L83:  */
L84: function isFresh(entry, now) {
L85:   return typeof entry?.fetchedAt === "number" && now - entry.fetchedAt < TTL_MS;
L86: }
L87: 
L88: /**
L89:  * @param {typeof globalThis.fetch} fetch
L90:  * @param {string} url
L91:  * @param {number} timeoutMs
L92:  */
L93: async function getJson(fetch, url, timeoutMs) {
L94:   const res = await fetch(url, {
L95:     headers: { accept: "application/json" },
L96:     signal: AbortSignal.timeout(timeoutMs),
L97:   });
L98:   if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
L99:   const text = await res.text();
L100:   if (text.length > MAX_BYTES) throw new Error(`response too large: ${url}`);
L101:   return JSON.parse(text);
L102: }
L103: 
L104: /**
L105:  * One refresh of every source that is stale (or all, with force). Never throws.
L106:  *
L107:  * @param {{fetch: typeof globalThis.fetch, dir: string, now: number,
L108:  *   timeoutMs?: number, force?: boolean}} opts
L109:  * @returns {Promise<{superindex: string, scores: string, ids: string}>}
L110:  *   per source: "fresh" (not due), "updated", or "failed: <reason>"
L111:  */
L112: export async function refreshMetrics({ fetch, dir, now, timeoutMs = FETCH_TIMEOUT_MS, force }) {
L113:   const prev = readMetrics(dir) ?? {};
L114:   /** @param {{fetchedAt?: unknown} | undefined} s */
L115:   const due = (s) => force || !isFresh(s, now);
L116:   const next = { ...prev };
L117:   const report = { superindex: "fresh", scores: "fresh", ids: "fresh" };
